package com.muoniumplayer.core.audio.ffmpeg;

import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.util.Base64;

/** Generated test tones only; PKCS12 is a self-signed localhost fixture, password test-only. */
final class AudioTestFixtures {
    private AudioTestFixtures() { }
    static byte[] pcm16(int rate, int channels, int frames) {
        boolean extended = channels > 2;
        int header = extended ? 68 : 44;
        ByteBuffer b = ByteBuffer.allocate(header + frames * channels * 2).order(ByteOrder.LITTLE_ENDIAN);
        b.putInt(0x46464952).putInt(b.capacity() - 8).putInt(0x45564157).putInt(0x20746d66);
        b.putInt(extended ? 40 : 16).putShort((short) (extended ? 65534 : 1)).putShort((short) channels);
        b.putInt(rate).putInt(rate * channels * 2).putShort((short) (channels * 2)).putShort((short) 16);
        if (extended) {
            b.putShort((short) 22).putShort((short) 16).putInt(channels == 6 ? 0x3f : 0x63f);
            b.putInt(1).putShort((short) 0).putShort((short) 0x10).putLong(0x719b3800aa000080L);
        }
        b.putInt(0x61746164).putInt(frames * channels * 2);
        for (int f = 0; f < frames; f++) for (int c = 0; c < channels; c++) b.putShort(sample(f, c));
        return b.array();
    }
    static short sample(int frame, int channel) { return (short) ((frame * 97 + channel * 1009) % 60001 - 30000); }
    static byte[] float32() {
        float[] data = {0.0f, -0.0f, 0.000000123f, -0.000000123f, 0.75f, -0.75f, 1.25f, -1.25f};
        ByteBuffer b = ByteBuffer.allocate(44 + data.length * 4).order(ByteOrder.LITTLE_ENDIAN);
        b.putInt(0x46464952).putInt(b.capacity() - 8).putInt(0x45564157).putInt(0x20746d66).putInt(16);
        b.putShort((short)3).putShort((short)1).putInt(48000).putInt(192000).putShort((short)4).putShort((short)32);
        b.putInt(0x61746164).putInt(data.length * 4);
        for (float value : data) b.putFloat(value);
        return b.array();
    }
    static byte[] mp3() { return Base64.getDecoder().decode("" ); }

    static byte[] flac() { return Base64.getDecoder().decode("" ); }

    static byte[] segment0() { return Base64.getDecoder().decode("" ); }

    static byte[] segment1() { return Base64.getDecoder().decode("" ); }

    static byte[] localhostKeyStore() { return Base64.getDecoder().decode("" ); }

    private static final int METADATA_BYTES = 42, BLOCK_SIZE = 16, CHANNELS = 2, SAMPLE_RATE = 44100;
    static byte[] constantFlac(int bits, int frames, long totalSamples) throws java.io.IOException {
        byte[] metadata = new byte[METADATA_BYTES];
        ByteBuffer info = ByteBuffer.wrap(metadata).order(ByteOrder.BIG_ENDIAN);
        info.put("fLaC".getBytes(java.nio.charset.StandardCharsets.US_ASCII));
        info.putInt(0x80000022); // 最后一个元数据块，34 字节 STREAMINFO。
        info.putShort((short) BLOCK_SIZE);
        info.putShort((short) BLOCK_SIZE);
        info.position(18);
        info.putLong(((long) SAMPLE_RATE << 44) | ((long) (CHANNELS - 1) << 41)
                | ((long) (bits - 1) << 36) | totalSamples);
        java.io.ByteArrayOutputStream output = new java.io.ByteArrayOutputStream();
        output.write(metadata);
        for (int index = 0; index < frames; index++) {
            java.io.ByteArrayOutputStream frame = new java.io.ByteArrayOutputStream();
            int depthCode = bits == 8 ? 1 : bits == 16 ? 4 : 6;
            frame.write(new byte[]{(byte) 0xff, (byte) 0xf8, 0x69,
                    (byte) (0x10 | (depthCode << 1)), (byte) index, BLOCK_SIZE - 1});
            frame.write(crc(frame.toByteArray(), 8, 0x07));
            for (int channel = 0; channel < CHANNELS; channel++) {
                frame.write(0); // 常量子帧，无 wasted bits。
                int value = sampleValue(bits, channel);
                for (int octet = bits / 8 - 1; octet >= 0; octet--) frame.write(value >>> (8 * octet));
            }
            int checksum = crc(frame.toByteArray(), 16, 0x8005);
            frame.write(checksum >>> 8);
            frame.write(checksum);
            frame.writeTo(output);
        }
        return output.toByteArray();
    }

    private static int sampleValue(int bits, int channel) {
        int left = bits == 8 ? 0x12 : bits == 16 ? 0x1234 : 0x123456;
        int right = bits == 8 ? -0x23 : bits == 16 ? -0x2345 : -0x234567;
        return channel == 0 ? left : right;
    }

    private static int crc(byte[] bytes, int bits, int polynomial) {
        int checksum = 0;
        int topBit = 1 << (bits - 1);
        int mask = (1 << bits) - 1;
        for (byte value : bytes) {
            checksum ^= (value & 0xff) << (bits - 8);
            for (int bit = 0; bit < 8; bit++) {
                checksum = ((checksum << 1) ^ ((checksum & topBit) != 0 ? polynomial : 0)) & mask;
            }
        }
        return checksum;
    }
}
